    public function findAll()
    {
        $expr = $this->_em->createQueryBuilder()->expr();
        $andX = $expr->andX(
            $expr->eq('bl.deleted', 0),
            $expr->eq('bl.published', 1),
            $expr->eq('bl.isPublic', 1)
        );

        return $this->createQueryBuilder('bl')
                ->where($andX)
                ->orderBy('bl.id', 'DESC')
                ->getQuery()
                ->execute();
    }

    public function getAllRegulations()
    {
        $expr = $this->_em->createQueryBuilder()->expr();

        return $this->createQueryBuilder('bl')
                ->orderBy('bl.id', 'DESC')
                ->getQuery()
                ->execute();
    }

    public function findRegulationsByAgency($agency)
