    public function searchByDetails($search_term)
    {
        $expr = $this->_em->createQueryBuilder()->expr();
        $andX = $expr->andX(
            $expr->eq('r.deleted', ":deleted"),
            $expr->eq('r.published', ":published"),
            $expr->eq('r.isPublic', ":isPublic")
        );
        $orX = $expr->orX(
            $expr->like('r.title', ':title'),
            $expr->like('r.description', ':description'),
            $expr->like('r.keywords', ':keywords'),
            $expr->like('r.closingDate', ':closingDate'),
            $expr->like('a.name', ':agency'),
            $expr->like('i.name', ':industry'),
            $expr->like('r.tags', ':tags'),
            $expr->like('r.specificInstructions', ':specificInstructions')
        );

        $params = [];
        $params = [
            'published' => 1,
            'isPublic' => 1,
            'deleted' => 0,
        ];
        $params['title'] = "%" . $search_term . "%";
        $params['description'] = "%". $search_term."%";
        $params['closingDate'] = "%". $search_term."%";
        $params['agency'] = "%". $search_term."%";
        $params['tags'] = "%". $search_term."%";
        $params['keywords'] = "%". $search_term."%";
        $params['specificInstructions'] = "%". $search_term."%";
        $params['industry'] = "%". $search_term."%";
        $andX->add($orX);
        $qb = $this->createQueryBuilder('r')
                ->leftJoin('r.industry', 'i')
                ->leftJoin('r.agency', 'a')
                ->where($andX)
                ->orderBy('r.title', 'ASC')
                ->setParameters($params)
                ->getQuery()->getResult();
        return $qb;
    }

