    public function getAllPublishedAndUnpublishedRegulations($published = true)
    {
        $expr = $this->_em->createQueryBuilder()->expr();
        $andX = $expr->andX(
            $expr->eq('bl.deleted', 0)
        );

        if ($published) {
            $andX->add(
                $expr->eq('bl.published', 1)
            );
        } else {
            $andX->add(
                $expr->eq('bl.published', 0)
            );
        }

        return $this->createQueryBuilder('bl')
            ->where($andX)
            ->getQuery()
            ->getResult();
    }



