    /**
     * Get Regulations with Comments Greater than Ten order by Publish Date
     *
     * @return EntityRepository
     */
    public function getRegulationsWithCommentsGreaterThenTen()
    {
        $expr = $this->_em->createQueryBuilder()->expr();
        return $this->_em->createQueryBuilder()
            ->addSelect('r.id')
            ->addSelect('COUNT(c.comment) as comment_count')
            ->from('NoticeCommentBundle:Regulation', 'r')
            ->leftJoin('r.comments', 'c')
            ->where(
                $expr->andX(
                    $expr->eq('r.deleted', '0'),
                    $expr->eq('r.consultationStage', 1),
                    $expr->eq('r.published', 1),
                    $expr->eq('r.isPublic', 1)
                )
            )
            ->groupBy('r.id')
            ->having($expr->gte('comment_count', '10'))
            ->setMaxResults(1)
            ->orderBy('comment_count', 'DESC')
            ->getQuery()
            ->getResult();
    }

    /**
     * Count Comments for regulations per agreement agreement
     *
     * @return EntityRepository
     */
    public function getCategorizedCommentsPerRegulation(int $regulation_id)
    {
        $expr = $this->_em->createQueryBuilder()->expr();
        return $this->_em->createQueryBuilder()
            ->addSelect('c.id')
            ->addSelect('c.position')
            ->from('NoticeCommentBundle:Regulation', 'r')
            ->leftJoin('r.comments', 'c')
            ->where(
                $expr->andX(
                    $expr->eq('r.deleted', '0'),
                    $expr->eq('c.regulation', ':regulation'),
                    $expr->eq('r.published', 1),
                    $expr->eq('r.isPublic', 1)
                )
            )
            ->setParameter('regulation', $regulation_id)
            ->orderBy('r.id', 'DESC')
            ->getQuery()
            ->getResult();
    }

    /**
     * Get regulations with the largest number of likes
     *
     * @return Entity Respostory
     */
    public function getRegulationsWithLargestExpression()
    {
        $expr = $this->_em->createQueryBuilder()->expr();
        return $this->_em->createQueryBuilder()
            ->addSelect('v.id')
            ->addSelect('SUM(l.id) AS likes_count')
            ->from('NoticeCommentBundle:Comment', 'u')
            ->leftJoin('u.regulation', 'v')
            ->leftJoin('u.likes', 'l')
            ->where(
                $expr->andX(
                    $expr->eq('v.deleted', 0),
                    $expr->eq('v.checkClosing', 1),
                    $expr->eq('v.published', 1),
                    $expr->eq('v.isPublic', 1),
                    $expr->isNull('u.parent')
                )
            )->groupBy('v.id')
            ->orderBy('likes_count', 'DESC')
            ->having('sum(l.id) > 10')
            ->getQuery()
            ->setMaxResults(1)
            ->getResult();
    }

