    public function getRegulationsCountPerIndustry()
    {
        return $this->getEntityManager()
            ->createQuery(
                'SELECT i.id, count(r.id) as regulation_count, i.name
                FROM NoticeCommentBundle:Regulation r INNER JOIN
                WebmastersAfricaLicenseBundle:BusinessIndustry i
                WITH r.industry = i.id WHERE i.deleted = 0 AND r.published = 1 AND r.isPublic = 0
                GROUP BY r.id'
            )->getResult();
    }

    /**
