    }

    public function searchByIndustryKeyword($industry, $keyword)
    {
        $expr = $this->_em->createQueryBuilder()->expr();
        $andX = $expr->andX(
            $expr->eq('bl.deleted', 0),
            $expr->like('i.name', ":industry"),
            $expr->eq('bl.published', 1),
            $expr->eq('bl.isPublic', 1)
        );
        $orX = $expr->orX(
            $expr->like('bl.title', ':name'),
            $expr->like('bl.description', ':description'),
            $expr->like('i.name', ':industry_name'),
            $expr->like('bl.keywords', ':keywords'),
            $expr->like('a.name', ':agency')
        );
        $andX->add($orX);
        $params['industry'] = $industry;
        $params['industry_name'] = "%" .$keyword. "%";
        $params['agency'] = "%" .$keyword. "%";
        $params['keywords'] = "%" .$keyword. "%";
        $params['name'] = "%" .$keyword. "%";
        $params['description'] = "%" .$keyword. "%";
        return $this->createQueryBuilder('bl')
            ->leftJoin('bl.agency', 'a')
            ->leftJoin('bl.industry', 'i')
            ->where($andX)
            ->setParameters($params)
            ->orderBy('bl.id', 'DESC')
            ->getQuery()
            ->getResult();
    }

