    public function getDashLicense($agency)
    {
        $expr = $this->_em->createQueryBuilder()->expr();
        $andX = $expr->andX(
            $expr->eq('bl.deleted', ':deleted'),
            $expr->in('bl.agency', ':agency'),
            $expr->eq('bl.checkClosing', 1),
            $expr->eq('bl.published', 1),
            $expr->eq('bl.isPublic', 1)
        );

        return $this->createQueryBuilder('bl')
            ->where($andX)
            ->orderBy('bl.id', 'DESC')
            ->setParameters(
                [
                    'deleted' => 0,
                    'agency' => $agency
                ]
            )
            ->setMaxResults(5)
            ->getQuery()
            ->getResult();
    }

    public function getNumberOfLicensesPerAgency()
    {
        $expr = $this->_em->createQueryBuilder()->expr();
        $result = $this->_em->createQueryBuilder()
            ->addSelect('ba.title')
            ->addSelect('COUNT(bl.id) as number_of_licenses')
            ->from('NoticeCommentBundle:Regulation', 'bl')
            ->innerJoin('bl.agency', 'ba')
            ->where(
                $expr->andX(
                    $expr->eq('bl.deleted', "0"),
                    $expr->eq('ba.deleted', "0"),
                    $expr->eq('bl.published', '1'),
                    $expr->eq('bl.isPublic', 1)
                )
            )
            ->groupBy('ba.title')
            ->orderBy('number_of_licenses', 'DESC')
            ->getQuery()
            ->getResult();
        return $result;
    }
